SELECT CASE WHEN amount >= 1440 THEN 'high' WHEN amount >= 390 THEN 'mid' ELSE 'low' END AS amount_bucket, DATE_TRUNC('MONTH', paid_at) AS paid_month, status, ROUND(STDDEV(amount), 2) AS stddev_amount, COUNT(*) AS row_count, COUNT(amount) AS amount_count FROM payments WHERE method = 'cash' AND status = 'FAILED' GROUP BY CASE WHEN amount >= 1440 THEN 'high' WHEN amount >= 390 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', paid_at), status HAVING COUNT(*) > 1 ORDER BY row_count DESC;
